time-to-burn-binary-tree.javascript:
class Node { constructor(val) { this.val = val; this.left = null; this.right = null; } }
function buildTree(tokens) {
  if (tokens.length === 0 || tokens[0] === 'N') return null;
  const root = new Node(parseInt(tokens[0]));
  const q = [root];
  let i = 1;
  while (q.length && i < tokens.length) {
    const node = q.shift();
    if (i < tokens.length) {
      const v = tokens[i++];
      if (v !== 'N') { node.left = new Node(parseInt(v)); q.push(node.left); }
    }
    if (i < tokens.length) {
      const v = tokens[i++];
      if (v !== 'N') { node.right = new Node(parseInt(v)); q.push(node.right); }
    }
  }
  return root;
}
